import { CalendarDays, CheckCheck, Ellipsis, Plus, Share2 } from "@/components/ui/Iconly";
import { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useToast } from "@/components/ui/ToastProvider";

const IMG = {"top": ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"], "man": "data:image/jpeg;base64,", "w1": "data:image/jpeg;base64,", "wb": "data:image/jpeg;base64,", "wo": "data:image/jpeg;base64,", "old": "data:image/jpeg;base64,"};
const BADGES = [["2", "b"], ["3", "b"], ["2", "r"], ["1", "r"], ["+", "w"], ["1", "r"], ["+", "w"], ["+", "w"]] as const;
const TASKS = [["Room|Requested", 807, 111], ["Room|Confirmed", 909, 112], ["Farmer|Updates", 809, 197], ["Pig|Monitoring", 909, 197], ["Payment|Reminder", 809, 278], ["Rental|Complete", 909, 278]] as const;
type Point = [number, number, string];

function Text({ x, y, value, muted = false, bold = false }: { x: number; y: number; value: string; muted?: boolean; bold?: boolean }) {
  return <div className={`case-canvas-tx${muted ? " muted" : ""}${bold ? " bold" : ""}`} style={{ left: x, top: y }}>{value.split("|").map((line) => <div key={line}>{line}</div>)}</div>;
}

function Photo({ x, y, src, className = "case-canvas-photo" }: { x: number; y: number; src: string; className?: string }) {
  return <img className={className} src={src} alt="" style={{ left: x - 22, top: y - 22 }} />;
}

function Row({ x = 324, y, src, value, done, dots, muted, bold, onAction }: { x?: number; y: number; src?: string; value: string; done?: boolean; dots?: boolean; muted?: boolean; bold?: boolean; onAction?: () => void }) {
  return <>
    {src ? <Photo x={x} y={y} src={src} /> : <button type="button" className="case-canvas-plus" aria-label={`${value} action`} style={{ left: x - 20, top: y - 20 }} onClick={onAction}><Plus size={18} /></button>}
    <Text x={x + 28} y={y - 13} value={value} muted={muted} bold={bold} />
    {done && <><span className="case-canvas-icon" style={{ left: x + 109, top: y - 12 }}><CheckCheck size={19} /></span><button type="button" className="case-canvas-circle" aria-label={`${value} calendar`} style={{ left: x + 136, top: y - 21 }} onClick={onAction}><CalendarDays size={17} /></button></>}
    {dots && <button type="button" className="case-canvas-icon case-canvas-icon-button" aria-label={`${value} more actions`} style={{ left: x + 145, top: y - 12 }} onClick={onAction}><Ellipsis size={18} /></button>}
  </>;
}

function Wires() {
  const points: Point[] = [[39, 270, "#8aa6e0"], [262, 181, "#8aa6e0"], [262, 303, "#e8777a"], [293, 133, "#8aa6e0"], [293, 183, "#8aa6e0"], [293, 235, "#8aa6e0"], [293, 285, "#e8777a"], [293, 334, "#e8777a"], [513, 133, "#8aa6e0"], [513, 183, "#8aa6e0"], [513, 235, "#8aa6e0"], [513, 285, "#e8777a"], [513, 334, "#e8777a"], [545, 235, "#8aa6e0"], [545, 285, "#e8777a"], [766, 133, "#e8777a"], [766, 183, "#e8777a"], [766, 231, "#e8777a"], [766, 285, "#aab"], [766, 334, "#e8777a"]];
  return <svg className="case-canvas-wires" width="1055" height="426" viewBox="0 0 1055 426" fill="none" strokeWidth="1.2" aria-hidden="true">
    <g stroke="#8aa6e0"><path d="M262 181C280 181 275 133 293 133M262 181H293M262 181C280 181 275 235 293 235" /></g>
    <g stroke="#e8777a"><path d="M262 303C279 303 276 285 293 285M262 303C279 303 276 334 293 334" /></g>
    <g stroke="#8aa6e0"><path d="M513 133H522Q530 133 530 141V227Q530 235 538 235H545M513 183H530" /></g>
    <g stroke="#e8777a" strokeDasharray="4 3"><path d="M513 285H545M513 334H522Q530 334 530 326V293Q530 285 538 285M545 235V285" /></g>
    <path d="M766 231C792 231 784 166 804 157" stroke="#111" strokeWidth="1.4" />
    <path d="M803 148L821 160L811 162L816 171L811 173L806 164L800 169Z" fill="#000" stroke="#fff" strokeWidth="1.2" />
    {points.map(([x, y, color], index) => <g key={index}><circle cx={x} cy={y} r="7" fill={color} opacity=".18" /><circle cx={x} cy={y} r="3.2" fill={color} /></g>)}
  </svg>;
}

export default function CaseManagementCanvas() {
  const navigate = useNavigate();
  const toast = useToast();
  const viewportRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(1);
  const [widthScale, setWidthScale] = useState(1);
  const [selectedTask, setSelectedTask] = useState(0);
  const [status, setStatus] = useState("");
  const handleCanvasAction = async (label: string) => {
    if (label === "Add") {
      setStatus("Add workflow item action selected");
      toast.info("Add workflow item", "Use the workflow actions below to add a rental task.");
      return;
    }
    if (label === "Calendar") {
      setStatus("Calendar opened");
      navigate("/admin/rentals");
      return;
    }
    try {
      await navigator.clipboard.writeText(window.location.href);
      setStatus("Workflow link copied");
      toast.success("Workflow link copied", "Share the copied link with your team.");
    } catch (error) {
      toast.error("Unable to copy workflow link", error instanceof Error ? error.message : "Clipboard access was denied.");
    }
  };

  useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const updateScale = () => {
      setScale(viewport.clientWidth / 1055);
      setWidthScale(viewport.clientWidth / 1035);
    };
    updateScale();
    const observer = new ResizeObserver(updateScale);
    observer.observe(viewport);
    return () => observer.disconnect();
  }, []);

  return <div ref={viewportRef} className="case-canvas-viewport" style={{ height: 426 * scale }} aria-label="Pig room rental workflow">
    <div className="case-canvas" style={{ transform: `translateX(${-8 * widthScale}px) scaleX(${widthScale}) scaleY(${scale})` }}>
    <svg className="case-canvas-shell" width="1055" height="426" viewBox="0 0 1055 426" aria-hidden="true"><path d="M48 12H310C326 12 334 20 337 36V50Q337 75 362 75H692Q717 75 717 50V36C720 20 728 12 744 12H1003Q1043 12 1043 52V378Q1043 418 1003 418H48Q8 418 8 378V52Q8 12 48 12Z" fill="#e8e9ee" /><path d="M337 12H717V36C720 20 728 12 744 12H1003" fill="none" /></svg>
    <div className="case-canvas-title">Pig Room Rental Workflow</div>
    <div className="case-canvas-status" role="status" aria-live="polite">{status}</div>
    <div className="case-canvas-top">{BADGES.map(([badge, tone], index) => <span key={index}><img className="case-canvas-top-photo" alt="" src={IMG.top[index]} style={{ left: 347 + 45 * index, top: 12 }} /><span className={`case-canvas-badge${tone === "w" ? " white" : ""}`} style={{ left: 360 + 45 * index, top: 52, background: tone === "b" ? "#7f9fe0" : tone === "r" ? "#e8636a" : undefined }}>{badge}</span></span>)}{[["Add", Plus], ["Share", Share2], ["Calendar", CalendarDays]].map(([label, Icon], index) => <button type="button" className="case-canvas-circle" aria-label={label as string} key={label as string} style={{ left: 893 + 46 * index, top: 32 }} onClick={() => handleCanvasAction(label as string)}><Icon size={17} /></button>)}</div>
    <div className="case-canvas-card" style={{ left: 39 }} /><div className="case-canvas-card" style={{ left: 291 }} /><div className="case-canvas-card" style={{ left: 543 }} /><div className="case-canvas-tasks" /><Wires />
    <Photo x={85} y={133} src={IMG.man} /><span className="case-canvas-icon" style={{ left: 178, top: 120 }}><CheckCheck size={19} /></span><span className="case-canvas-circle" style={{ left: 206, top: 111 }}><CalendarDays size={17} /></span><Text x={65} y={177} value="Review rental request" /><div className="case-canvas-rule" />
    <Photo x={85} y={270} src={IMG.man} /><span className="case-canvas-icon" style={{ left: 178, top: 258 }}><CheckCheck size={19} /></span><span className="case-canvas-circle" style={{ left: 206, top: 249 }}><CalendarDays size={17} /></span><Text x={65} y={313} value="Confirm room|availability" />
    <Row y={133} src={IMG.w1} value="Select room|and duration" done onAction={() => setStatus("Room duration calendar selected")} /><Row y={183} src={IMG.w1} value="Review farmer|details" done onAction={() => setStatus("Farmer details calendar selected")} /><Row y={235} src={IMG.w1} value="Confirm rental|dates" done onAction={() => setStatus("Rental dates calendar selected")} /><Row y={285} src={IMG.wb} value="Assign pig|room" dots bold onAction={() => setStatus("Pig room actions selected")} /><Row y={334} src={IMG.wo} value="Share camera|access" dots bold onAction={() => setStatus("Camera access actions selected")} />
    <Row x={578} y={133} value="Record payment|status" muted onAction={() => setStatus("Payment action selected")} /><Row x={578} y={183} value="Schedule farm|updates" muted onAction={() => setStatus("Farm update action selected")} /><Row x={578} y={233} src={IMG.old} value="Monitor pig|wellbeing" dots bold onAction={() => setStatus("Pig monitoring actions selected")} /><Row x={578} y={285} src={IMG.wb} value="Send rental|reminders" dots muted onAction={() => setStatus("Rental reminder actions selected")} /><Row x={578} y={334} value="Close rental|and review" muted onAction={() => setStatus("Close rental action selected")} />
    {TASKS.map(([value, left, top], index) => <button type="button" key={value} className={`case-canvas-tile${selectedTask === index ? " active" : ""}`} aria-pressed={selectedTask === index} style={{ left, top, height: index === 0 ? 80 : 77 }} onClick={() => { setSelectedTask(index); setStatus(`${value.replace("|", " ")} selected`); }}>{value.split("|").map((line) => <div key={line}>{line}</div>)}</button>)}
    {["Rental Request", "Room & Farmer", "Farm Monitoring", "Next Actions"].map((label, index) => <div key={label} className="case-canvas-label" style={{ left: 39 + 252 * index }}>{label}</div>)}
    </div>
  </div>;
}
